    /// Автоматически обходит все страницы курсорной пагинации метода `list_runs`.
    pub fn list_runs_all(&self, params: Option<&BTreeMap<String, String>>) -> Result<Vec<JsonValue>, TungoError> {
        let mut p: BTreeMap<String, String> = params.cloned().unwrap_or_default();
        let mut items: Vec<JsonValue> = Vec::new();
        loop {
            let page = self.list_runs(Some(&p))?;
            if let Some(arr) = page.get("data").and_then(|v| v.as_array()) {
                items.extend(arr.iter().cloned());
            }
            match page.get("next_cursor").and_then(|v| v.as_str()) {
                Some(c) if !c.is_empty() => { p.insert("cursor".to_string(), c.to_string()); }
                _ => break,
            }
        }
        Ok(items)
    }

